  console.log('UNHANDLED REJECTION:', err && err.code, err && err.message)
})

async function main () {
  for (const kind of ['sync', 'async']) {
    const app = Fastify()
    app.addHook('onSend', kind === 'async'
      ? async function (req, reply, payload) { return payload }
      : function (req, reply, payload, done) { done(null, payload) })
    app.get('/', (req, reply) => {
      reply.header('x-bad', 'bad\nvalue')
      reply.send('hello')
    })
    try {
      const res = await app.inject('/')
      console.log(kind, '->', res.statusCode, JSON.stringify(res.payload.slice(0, 160)))
    } catch (err) {
      console.log(kind, 'inject threw', err.code, err.message)
    }
    await new Promise(r => setTimeout(r, 200))
  }
}
main()
